//! The reader's learned data, `scan.bin` (generated by the OCR prototype,
//! `tools/hud-ocr/genbin.py`, from captures with known values). Records:
//! `u8 kind, u8 key, u8 feature, u16 w, u16 h, w*h u8`.
//!
//! Not shipped and not in the repo: it is learned from the game's HUD font,
//! so it is built on the user's machine (by the app itself, later) and
//! loaded at runtime with [`load`]. Until then the reader reads nothing.
//!
//! - kind 1: an anchor template (key = [`Anchor`] index, feature 0 =
//!   brightness ink, 1 = shadow ink), from the reference capture and from
//!   glare captures;
//! - kind 2: a mean glyph template (key = the char);
//! - kind 3: a digit exemplar (key = the char): every labelled digit cut
//!   from the training captures, for nearest-example classification.
//!
//! All at the reference HUD scale (2560x1440).

use std::path::Path;
use std::sync::OnceLock;

use svc_capture::vision::Gray;

const MAGIC: &[u8] = b"SLHUD1";

/// The panel parts the locator votes with, in reference pixels from the
/// MASS label's top-left: (left, top) of each template.
pub const ANCHOR_OFFSETS: [(f32, f32); 4] = [
    (1.0, -76.0),  // SCAN RESULTS header
    (0.0, 0.0),    // MASS / RESIST / INSTAB labels
    (-1.0, 130.0), // COMPOSITION
    (-7.0, 154.0), // the composition bar's frame
];

pub struct AnchorTemplate {
    pub anchor: usize,
    /// 0: brightness ink, 1: shadow ink.
    pub feature: u8,
    pub t: Gray,
}

pub struct Data {
    pub anchors: Vec<AnchorTemplate>,
    pub glyphs: Vec<(char, Gray)>,
    pub exemplars: Vec<(char, Gray)>,
}

static DATA: OnceLock<Data> = OnceLock::new();
static EMPTY: Data = Data {
    anchors: Vec::new(),
    glyphs: Vec::new(),
    exemplars: Vec::new(),
};

/// Load the learned data from `path`, once: later calls keep what loaded.
/// `Ok(false)`: there is no file there (yet).
pub fn load(path: &Path) -> Result<bool, String> {
    if DATA.get().is_some() {
        return Ok(true);
    }
    let bin = match std::fs::read(path) {
        Ok(bin) => bin,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(false),
        Err(e) => return Err(format!("{}: {e}", path.display())),
    };
    let d = parse(&bin).map_err(|e| format!("{}: {e}", path.display()))?;
    let _ = DATA.set(d);
    Ok(true)
}

/// Whether [`load`] found the data.
pub fn loaded() -> bool {
    DATA.get().is_some()
}

/// The loaded data; empty (nothing to match against) before [`load`].
pub fn data() -> &'static Data {
    DATA.get().unwrap_or(&EMPTY)
}

pub fn parse(bin: &[u8]) -> Result<Data, String> {
    if !bin.starts_with(MAGIC) {
        return Err("not a scan.bin (bad magic)".into());
    }
    let mut d = Data {
        anchors: vec![],
        glyphs: vec![],
        exemplars: vec![],
    };
    let mut i = MAGIC.len();
    while i + 7 <= bin.len() {
        let (kind, key, feature) = (bin[i], bin[i + 1], bin[i + 2]);
        let w = u16::from_le_bytes([bin[i + 3], bin[i + 4]]) as usize;
        let h = u16::from_le_bytes([bin[i + 5], bin[i + 6]]) as usize;
        let px = bin
            .get(i + 7..i + 7 + w * h)
            .ok_or_else(|| format!("record at {i} runs past the end"))?;
        i += 7 + w * h;
        let g = Gray::from_u8(w, h, px);
        match kind {
            1 => d.anchors.push(AnchorTemplate {
                anchor: key as usize,
                feature,
                t: g,
            }),
            2 => d.glyphs.push((key as char, g)),
            3 => d.exemplars.push((key as char, g)),
            _ => {}
        }
    }
    Ok(d)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn record(kind: u8, key: u8, feature: u8, w: u16, h: u16) -> Vec<u8> {
        let mut r = vec![kind, key, feature];
        r.extend(w.to_le_bytes());
        r.extend(h.to_le_bytes());
        r.extend(std::iter::repeat_n(200u8, (w * h) as usize));
        r
    }

    #[test]
    fn parses_each_kind() {
        let mut bin = MAGIC.to_vec();
        bin.extend(record(1, 3, 1, 4, 2));
        bin.extend(record(2, b'%', 0, 3, 5));
        bin.extend(record(3, b'7', 0, 2, 2));
        let d = parse(&bin).unwrap();
        assert_eq!((d.anchors[0].anchor, d.anchors[0].feature), (3, 1));
        assert_eq!(d.glyphs[0].0, '%');
        assert_eq!(d.exemplars[0].0, '7');
        assert_eq!(d.exemplars[0].1.v.len(), 4);
    }

    #[test]
    fn rejects_bad_magic_and_short_records() {
        assert!(parse(b"NOTHUD").is_err());
        let mut bin = MAGIC.to_vec();
        bin.extend(&record(3, b'1', 0, 4, 4)[..10]);
        assert!(parse(&bin).is_err());
    }

    #[test]
    fn a_missing_file_is_not_an_error() {
        assert_eq!(load(Path::new("no/such/scan.bin")), Ok(false));
    }
}
